inputs = ['wcde', 'uwi', 'xiza', 'ykk', 'ij']
outputs = ['wkdde', 'uzh', 'xyuxcgixf', 'ykk', 'yuxj']

print("Input/Output pairs:")
for i in range(len(inputs)):
    print(f"  {inputs[i]} -> {outputs[i]}")

print("\nAnalyzing differences:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    if inp != outp:
        print(f"  {inp} -> {outp} (different)")
    else:
        print(f"  {inp} -> {outp} (same)")

